import {describe,it,expect,vi} from 'vitest';
import {createGame} from '../shared/seed';
import {beginTurn} from '../shared/engine';
import {fallback} from '../shared/ai';
import {choose} from '../worker/index';
// Test-only binding fixture; production binding types are generated by Wrangler.
function binding(run:ReturnType<typeof vi.fn>){return {AI:{run},LOCAL_AI_ENABLED:'true'} as unknown as Env;}
describe('Workers AI boundary',()=>{
 it('reserves GLM output for the decision schema and counts empty completion usage',async()=>{const s=createGame();beginTurn(s);const run=vi.fn().mockResolvedValue({choices:[{message:{content:null}}],usage:{prompt_tokens:123,completion_tokens:650}});const result=await choose(s,'ger',binding(run),false);expect(result.source).toBe('fallback');expect(result.error).toContain('output budget');expect(s.usage.outputTokens).toBe(650);expect(run.mock.calls[0][1]).toMatchObject({max_completion_tokens:650,chat_template_kwargs:{enable_thinking:false},response_format:{type:'json_schema',json_schema:{name:'country_decision'}}});});
 it('normalizes GLM chat completions and reported usage',async()=>{const s=createGame();beginTurn(s);const d=fallback(s,'ger');const run=vi.fn().mockResolvedValue({choices:[{message:{content:JSON.stringify(d)}}],usage:{prompt_tokens:123,completion_tokens:87}});const result=await choose(s,'ger',binding(run),false);expect(result.source).toBe('llm');expect(s.usage.inputTokens).toBe(123);expect(s.usage.outputTokens).toBe(87);expect(s.progress!.calls).toBe(1);expect(run).toHaveBeenCalledOnce();});
 it('normalizes traditional model responses',async()=>{const s=createGame();beginTurn(s);const run=vi.fn().mockResolvedValue({response:JSON.stringify(fallback(s,'fra'))});expect((await choose(s,'fra',binding(run),false)).source).toBe('llm');});
 it('rejects malformed outputs, labels fallback and avoids repeated quota requests',async()=>{const s=createGame();beginTurn(s);const run=vi.fn().mockResolvedValue({response:'{"explanation":"invented","militaryActions":[]}'});const result=await choose(s,'ger',binding(run),false);expect(result.source).toBe('fallback');expect(result.error).toBeDefined();expect(s.usage.failed).toBe(1);await choose(s,'fra',binding(run),false);expect(run).toHaveBeenCalledOnce();});
 it('handles unavailable models and exhausted budgets without inventing inference',async()=>{const s=createGame();beginTurn(s);const run=vi.fn().mockRejectedValue(new Error('AI quota exhausted'));expect((await choose(s,'ger',binding(run),false)).source).toBe('fallback');expect(s.usage.status).toContain('Fallback');s.settings.callBudget=0;expect((await choose(s,'gbr',binding(run),false)).source).toBe('fallback');expect(run).toHaveBeenCalledOnce();});
});
